<script setup lang="ts">
import { ArrowRight, CalendarCheck, CalendarDays, Clock3, CreditCard, UserRound, Users } from '@lucide/vue'
import { SALON_TIMEZONE,formatXof } from '~~/shared/constants/business'
import type { SalonRole } from '~~/shared/constants/rbac'
definePageMeta({layout:'admin',middleware:'admin'})
type Dashboard={role?:SalonRole;counts:{today:number;upcoming:number;pending:number;confirmed:number;cancelled:number;newCustomers:number};receivedLast30Days?:number;awaitingDepositXof?:number;revenueMonthly?:Array<{month:string;amountXof:number}>;upcomingByDay:Array<{day:string;count:number}>;popularServices:Array<{name:string;visits:number;revenue?:number}>;recentAppointments:Array<{id:string;reference:string;status:string;startsAt:string;totalXof?:number;amountPaidXof?:number}>}
const{data,error,refresh}=await useFetch<Dashboard>('/api/admin/dashboard',{key:'admin-dashboard'})
const isOwner=computed(()=>data.value?.role!=='reception')
function date(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
function shortDate(value:string){const parts=value.split('-');const m=parts[1]??'';const y=parts[0]??'';return `${m}/${y.slice(2)}`}
function dayLabel(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,weekday:'short',day:'numeric'}).format(new Date(`${value}T12:00:00Z`))}
function maxOf(list:Array<{amountXof?:number;count?:number}>){return Math.max(1,...list.map((item)=>Number(item.amountXof??item.count??0)))}
const revenueBars=computed(()=>{const rows=data.value?.revenueMonthly||[];const max=maxOf(rows);return rows.map((row)=>({...row,percent:Math.round(row.amountXof/max*100)}))})
const loadBars=computed(()=>{const rows=data.value?.upcomingByDay||[];const max=maxOf(rows);return rows.map((row)=>({...row,percent:Math.round(row.count/max*100)}))})
useSeoMeta({title:'Administration — Vue d’ensemble',robots:'noindex,nofollow'})
</script>
<template><div><div class="admin-page-head"><div><span class="section-kicker">Votre activité</span><h1>Vue d’ensemble.</h1><p>Les chiffres affichés proviennent des enregistrements du salon.</p></div><button class="admin-inline-action" @click="refresh()">Actualiser</button></div><p v-if="error" class="admin-alert">Les indicateurs ne sont pas disponibles. Configurez Neon et le premier compte propriétaire, puis créez un salon actif.</p><template v-else-if="data"><div class="admin-metric-grid"><article class="admin-card admin-metric"><small>Rendez-vous aujourd’hui</small><strong>{{data.counts.today}}</strong><span>Créneaux au calendrier local</span></article><article class="admin-card admin-metric"><small>À venir</small><strong>{{data.counts.upcoming}}</strong><span>Réservés et actifs</span></article><article class="admin-card admin-metric"><small>En attente</small><strong>{{data.counts.pending}}</strong><span>Avec retenue valide</span></article><template v-if="isOwner"><article class="admin-card admin-metric"><small>Encaissements · 30 jours</small><strong>{{formatXof(data.receivedLast30Days||0)}}</strong><span>Transactions rapprochées uniquement</span></article><article class="admin-card admin-metric"><small>Acomptes en attente</small><strong>{{formatXof(data.awaitingDepositXof||0)}}</strong><span>Non comptés dans les recettes</span></article></template><article class="admin-card admin-metric"><small>Confirmés</small><strong>{{data.counts.confirmed}}</strong><span>30 derniers jours</span></article><article class="admin-card admin-metric"><small>Nouvelles clientes</small><strong>{{data.counts.newCustomers}}</strong><span>30 derniers jours</span></article><article class="admin-card admin-metric"><small>Annulés</small><strong>{{data.counts.cancelled}}</strong><span>30 derniers jours</span></article></div><div v-if="isOwner&&revenueBars.length" class="admin-card chart-card"><div class="admin-card__title"><h2>Encaissements · 6 mois</h2></div><div class="bar-chart"><div v-for="bar in revenueBars" :key="bar.month" class="bar-chart__col"><span class="bar-chart__value">{{formatXof(bar.amountXof)}}</span><div class="bar-chart__track"><div class="bar-chart__fill" :style="{height:`${Math.max(bar.percent,2)}%`}"/></div><small>{{shortDate(bar.month)}}</small></div></div></div><div class="admin-card chart-card"><div class="admin-card__title"><h2>Charge prévisionnelle · 7 jours</h2></div><div class="bar-chart"><div v-for="bar in loadBars" :key="bar.day" class="bar-chart__col"><span class="bar-chart__value">{{bar.count}} rdv</span><div class="bar-chart__track"><div class="bar-chart__fill is-teal" :style="{height:`${Math.max(bar.percent,2)}%`}"/></div><small>{{dayLabel(bar.day)}}</small></div></div></div><section class="admin-card"><div class="admin-card__title"><h2>Rendez-vous récents</h2><NuxtLink class="link-arrow" to="/admin/rendez-vous">Tout voir <ArrowRight :size="14"/></NuxtLink></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Référence</th><th>Date</th><th>Statut</th><th v-if="isOwner">Total</th><th v-if="isOwner">Encaissé</th></tr></thead><tbody><tr v-for="item in data.recentAppointments" :key="item.id"><td><strong>{{item.reference}}</strong></td><td>{{date(item.startsAt)}}</td><td><span class="status-pill">{{item.status}}</span></td><td v-if="isOwner">{{formatXof(item.totalXof||0)}}</td><td v-if="isOwner">{{formatXof(item.amountPaidXof||0)}}</td></tr><tr v-if="!data.recentAppointments.length"><td :colspan="isOwner?5:3" class="admin-empty">Aucun rendez-vous enregistré.</td></tr></tbody></table></div></section><div class="dashboard-lower"><section class="admin-card"><div class="admin-card__title"><h2>Prestations populaires</h2></div><div v-if="data.popularServices.length" class="popular-list"><div v-for="item in data.popularServices" :key="item.name"><span>{{item.name}}</span><strong>{{item.visits}} rendez-vous<template v-if="isOwner&&item.revenue"> · {{formatXof(item.revenue)}}</template></strong></div></div><div v-else class="admin-empty">Les données apparaîtront après les rendez-vous.</div></section><div class="dashboard-shortcuts"><NuxtLink to="/admin/calendrier"><CalendarDays :size="18"/> Calendrier</NuxtLink><NuxtLink to="/admin/clients"><Users :size="18"/> Clientes</NuxtLink><NuxtLink to="/admin/paiements"><CreditCard :size="18"/> Paiements</NuxtLink><NuxtLink to="/admin/prestations"><CalendarCheck :size="18"/> Prestations</NuxtLink></div></div></template></div></template>
<style scoped>.chart-card{margin-top:1rem}.bar-chart{display:flex;align-items:flex-end;gap:.6rem;padding:1rem 1.2rem 1.2rem}.bar-chart__col{flex:1;display:grid;grid-template-rows:auto 1fr auto;gap:.4rem;text-align:center}.bar-chart__value{font-size:.58rem;color:#877b73}.bar-chart__track{height:120px;display:flex;align-items:flex-end;border-bottom:1px solid #e8e0d8}.bar-chart__fill{width:100%;border-radius:.4rem .4rem 0 0;background:linear-gradient(180deg,#8a3a58,#6b2d45);min-height:4px;transition:height .3s}.bar-chart__fill.is-teal{background:linear-gradient(180deg,#3f7f77,#32635c)}.bar-chart__col small{color:#968981;font-size:.56rem;text-transform:capitalize}
.dashboard-lower{display:grid;grid-template-columns:1.2fr .8fr;gap:1rem;margin-top:1rem}.popular-list{padding:.5rem 1rem}.popular-list>div{display:flex;justify-content:space-between;gap:1rem;border-bottom:1px solid #eee7df;padding:.75rem 0;font-size:.69rem}.popular-list strong{color:#6b2d45;font-size:.63rem}.dashboard-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:.55rem}.dashboard-shortcuts a{display:flex;align-items:center;gap:.6rem;border:1px solid #e5dbd2;border-radius:.7rem;padding:1rem;color:#5b4d47;background:#fffdf9;font-size:.68rem}.dashboard-shortcuts svg{color:#6b2d45}@media(max-width:800px){.dashboard-lower{grid-template-columns:1fr}.bar-chart__track{height:80px}}</style>
